		}
		if len(batch.Clusters) > batchSize {
			t.Fatalf("batch %d holds %d clusters, batchSize is %d", batch.Index, len(batch.Clusters), batchSize)
		}
		if len(batch.Clusters) == 0 {
			t.Fatalf("batch %d is empty", batch.Index)
		}
