				t.Fatalf("batch %d contains unexpected cluster %q", batch.Index, id)
			}
			if prev, conflict := usedDomains[domain]; conflict {
				t.Fatalf("batch %d puts %q and %q in the same fault domain %q", batch.Index, prev, id, domain)
